package net.civeira.phylax.features.access.userfederatedidentity.domain.gateway;

import java.util.List;
import java.util.Optional;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.access.userfederatedidentity.domain.UserFederatedIdentity;
import net.civeira.phylax.features.access.userfederatedidentity.domain.UserFederatedIdentityRef;

public interface UserFederatedIdentityQueryRepositoryGateway {

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @return The items that would be returned by the query
   */
  long count(UserFederatedIdentityFilter filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param uid
   * @param filter a filter to retrieve only matching values
   * @return Retrieve one single value
   */
  boolean exists(String uid, Optional<UserFederatedIdentityFilter> filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @return The slide with some values
   */
  Optional<UserFederatedIdentity> find(UserFederatedIdentityFilter filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @return The slide with some values
   */
  List<UserFederatedIdentity> list(UserFederatedIdentityFilter filter);

  /**
   * Retrieve full data for a reference.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param reference a filter to retrieve only matching values
   * @return Retrieve one single value
   */
  UserFederatedIdentity resolve(UserFederatedIdentityRef reference);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param uid
   * @param filter a filter to retrieve only matching values
   * @return Retrieve one single value
   */
  Optional<UserFederatedIdentity> retrieve(String uid,
      Optional<UserFederatedIdentityFilter> filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @param cursor a cursor to order and skip
   * @return The slide with some values
   */
  Slider<UserFederatedIdentity> slide(UserFederatedIdentityFilter filter,
      UserFederatedIdentityCursor cursor);
}
